# CELL 9: RUN BATCH ANALYSIS   (Eir 2.0.13)
#
# Must sit after the anion-BVS cells, because process_single_cif calls
# anion_bvs_for_structure(). Keeping the runner here means Restart & Run All
# works top to bottom.

# Names the run depends on. A missing one here is a cell that was not run, or
# was run and raised part-way; either way the message should say which,
# because the alternative is a NameError several hundred structures in.
for _name in ('calculate_anion_bvs', 'anion_bvs_for_structure',
              'add_coordination_quality', 'expected_bond_length',
              'normaliser_translations', 'classify_pgrm',
              'reset_read_failures', 'report_read_failures',
              'may_visualise', 'reset_visualisations'):
    if _name not in globals():
        raise NameError(f"{_name}() is not defined. Run the cells above first.")

EIR_CIF_DIRECTORY = _EIR_RUN_DIRECTORY   # eir package: the folder passed in

if EIR_CIF_DIRECTORY is None:
    df = None
    print('\n\u2717 Analysis cancelled')
else:
    # v2.0.13: the read-failure register is per-run. Without the reset a
    # second batch in the same session reports the first batch's failures.
    reset_read_failures()
    reset_visualisations()
    df = batch_process_directory(EIR_CIF_DIRECTORY)

if df is not None and len(df):
    print('\n' + '=' * 78)
    print('BATCH PROCESSING COMPLETE')
    print('=' * 78)
    print(f"  Structures analysed : {df['filename'].nunique()}")
    print(f'  Sites analysed      : {len(df)}')

    # v2.0.13: anything that could not be READ, as opposed to anything that
    # was read and had nothing to report. Five metadata extractors used to
    # wrap their whole file read in a bare except and return an empty result,
    # so a failed read was indistinguishable from absent metadata - which is
    # why measurement_pressure_GPa appeared on 10 of 934 perovskites with no
    # way to tell which it meant.
    report_read_failures()

    print(f"\n  Results saved to: "
          f"{os.path.join(EIR_CIF_DIRECTORY, 'outputs')}")
    print('  Next: the post-processing cell, which adds coordination quality',
          'and the PGRM integrity gates.')
elif df is not None:
    print('\n\u2717 The batch produced no rows. Check the CIF directory and the',
          'failed-files CSV in outputs/.')
else:
    print('\n\u2717 Analysis failed')
